import{_ as a,o,c as t,a6 as i}from"./chunks/framework.mtgKxyez.js";const m=JSON.parse('{"title":"4. Self Practice","description":"","frontmatter":{},"headers":[],"relativePath":"en/intermediate/4.md","filePath":"en/intermediate/4.md"}'),c={name:"en/intermediate/4.md"};function l(n,e,s,r,h,d){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_4-self-practice" tabindex="-1">4. Self Practice <a class="header-anchor" href="#_4-self-practice" aria-label="Permalink to &quot;4. Self Practice&quot;">​</a></h1><h2 id="task-1-loop" tabindex="-1">Task 1: Loop <a class="header-anchor" href="#task-1-loop" aria-label="Permalink to &quot;Task 1: Loop&quot;">​</a></h2><p>Use the same task as the <a href="/YMSH_TMRobot_Textbook/en/basic/6.html">Basic self practice</a>, but repeat it six times.</p><h2 id="verification-1" tabindex="-1">Verification 1 <a class="header-anchor" href="#verification-1" aria-label="Permalink to &quot;Verification 1&quot;">​</a></h2><ol><li>The mahjong board position is not fixed. Check whether the arm can accurately place the mahjong block into a slot and repeat six times. It is recommended not to rotate the board more than 180°.</li><li>After repeating six times, check whether it automatically exits the project execution screen.</li></ol><div class="tip custom-block"><p class="custom-block-title">Small Tip</p><p>When running a loop, remember to pick up the mahjong block, or the arm will crash into it.</p></div><h2 id="answer-1" tabindex="-1">Answer 1 <a class="header-anchor" href="#answer-1" aria-label="Permalink to &quot;Answer 1&quot;">​</a></h2><p>Continue from the <a href="/YMSH_TMRobot_Textbook/en/basic/6.html">Basic self practice</a>.</p><ol><li>Add a counting variable.</li><li><code>Set</code>: after the last gripper release (<code>DO_0</code> is <code>L</code>), set the variable to <code>+= 1</code>.</li><li><code>If</code>: create the loop, for example by setting the variable condition to <code>&gt;= 6</code>. <ul><li><code>Yes</code>: same as the later part of the <a href="/YMSH_TMRobot_Textbook/en/basic/6.html">Basic self practice</a>, end the project.</li><li><code>No</code>: use <code>Goto</code> to connect back to <code>If</code> and close the loop. You can also directly draw the flow line back instead of using <code>Goto</code>.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Small Tip</p><p>There are many ways to count variables and write <code>If</code> conditions. This is only one example.</p></div><h2 id="task-2-fill-the-board" tabindex="-1">Task 2: Fill the Board <a class="header-anchor" href="#task-2-fill-the-board" aria-label="Permalink to &quot;Task 2: Fill the Board&quot;">​</a></h2><p>Place six mahjong blocks one by one into the six slots on the small mahjong board. The board position changes within a range and is not fixed.</p><h2 id="verification-2" tabindex="-1">Verification 2 <a class="header-anchor" href="#verification-2" aria-label="Permalink to &quot;Verification 2&quot;">​</a></h2><ol><li>The mahjong position is not fixed. Check whether the arm can accurately pick it up.</li><li>The small board position is not fixed. Check whether the mahjong blocks can fill all six slots in order, especially the middle row.</li><li>After filling all six slots, check whether it automatically exits the project execution screen.</li></ol><h2 id="answer-2" tabindex="-1">Answer 2 <a class="header-anchor" href="#answer-2" aria-label="Permalink to &quot;Answer 2&quot;">​</a></h2><p>Continue after finishing <a href="#task-1-loop">Task 1: Loop</a>.</p><ol><li><code>Pallet</code> (Vision Base): replace the original placement <code>Point</code> with <code>Pallet</code>.</li><li>Leave everything else unchanged.</li></ol><h2 id="task-3-stack-up" tabindex="-1">Task 3: Stack Up <a class="header-anchor" href="#task-3-stack-up" aria-label="Permalink to &quot;Task 3: Stack Up&quot;">​</a></h2><p>Stack three to five mahjong blocks vertically at the same place, and display in real time how many mahjong blocks have been stacked.</p><h2 id="verification-3" tabindex="-1">Verification 3 <a class="header-anchor" href="#verification-3" aria-label="Permalink to &quot;Verification 3&quot;">​</a></h2><ol><li>The mahjong block position is not fixed. Check whether the arm can accurately pick it up.</li><li>Check whether the mahjong blocks can be picked repeatedly and placed at the same position without triggering a collision error.</li><li>After the flow ends, check whether it automatically exits the project execution screen.</li></ol><h2 id="answer-3" tabindex="-1">Answer 3 <a class="header-anchor" href="#answer-3" aria-label="Permalink to &quot;Answer 3&quot;">​</a></h2><p>Continue after finishing <a href="#task-1-loop">Task 1: Loop</a>.</p><ol><li>Change the <code>If</code> condition so the loop runs the number of times you want, three to five times.</li><li>Change the <code>Set</code> that releases the gripper and increments the variable, and add coordinate parameterization to it.</li><li><code>Display</code>: add display information at the first step of the loop to show &quot;how many mahjong blocks have been stacked so far&quot; in real time.</li></ol><h2 id="task-4-choose-a-slot" tabindex="-1">Task 4: Choose a Slot <a class="header-anchor" href="#task-4-choose-a-slot" aria-label="Permalink to &quot;Task 4: Choose a Slot&quot;">​</a></h2><p>As before, pick up a mahjong block from an unfixed position. But when placing it on the small board, let the user freely choose one of the six slots, then continue the remaining placement and ending flow.</p><div class="tip custom-block"><p class="custom-block-title">Small Tip</p><p>The task does not require a loop. But if you want extra self practice, you can make the project run until all six slots have been chosen. If the user selects a slot that was already chosen, do not execute it and show an error message.</p></div><h2 id="verification-4" tabindex="-1">Verification 4 <a class="header-anchor" href="#verification-4" aria-label="Permalink to &quot;Verification 4&quot;">​</a></h2><ol><li>The mahjong position is not fixed. Check whether the arm can accurately pick it up.</li><li>After picking up the mahjong block, check whether a human-machine interaction window with six options appears.</li><li>After the user chooses a position, check whether the mahjong block is placed at the corresponding position, while the board position is not fixed.</li><li>After the flow ends, check whether it automatically exits the project execution screen.</li></ol><h2 id="answer-4" tabindex="-1">Answer 4 <a class="header-anchor" href="#answer-4" aria-label="Permalink to &quot;Answer 4&quot;">​</a></h2><p>Continue from the <a href="/YMSH_TMRobot_Textbook/en/basic/6.html">Basic self practice</a>.</p><ol><li><code>M-Decision</code>: before the original placement <code>Point</code>, add an <code>M-Decision</code> node with six options. You can name them yourself. Each option branch should correspond to one <code>Point</code> (Vision Base).</li></ol><div class="tip custom-block"><p class="custom-block-title">Small Tip</p><p>To complete the extension, let the project run a six-time loop and create six variables to record whether each slot has been chosen. Then use <code>If</code> to decide whether a chosen slot should show an error (<code>Display</code>) or whether an unchosen slot should place the block at that point (<code>Point</code>).</p><p>The six branches of <code>M-Decision</code> can change only the <code>Point</code>; the shared parts such as <code>Set</code> and <code>Wait for</code> can all connect back to the same place.</p></div>',33)])])}const f=a(c,[["render",l]]);export{m as __pageData,f as default};
